LowerBound:
var lo := 0;
var hi := |s|;
while lo < hi
    invariant 0 <= lo <= hi <= |s|
    invariant forall i :: 0 <= i < lo ==> s[i] < key
    invariant forall i :: hi <= i < |s| ==> key <= s[i]
    decreases hi - lo
{
    var mid := lo + (hi - lo) / 2;
    if s[mid] < key {
        lo := mid + 1;
    } else {
        hi := mid;
    }
}
p := lo;
